import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Brain, Download, AlertCircle, CheckCircle, Loader, MessageSquare, FileText, PlusCircle } from 'lucide-react';
import { apiService } from '../../services/api';

interface RAGProcessorProps {
  questions: string[];
  knowledgeBaseReady: boolean;
}

interface ProcessingResult {
  status: string;
  message: string;
  answers: Record<string, string>; // Backend returns answers as key-value pairs
  answers_generated: number;
  needs_context: string[];
  remaining_clarifications: number;
}

const RAGProcessorNew: React.FC<RAGProcessorProps> = ({ questions, knowledgeBaseReady }) => {
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingResult, setProcessingResult] = useState<ProcessingResult | null>(null);
  const [status, setStatus] = useState<'idle' | 'processing' | 'success' | 'error'>('idle');
  const [contextInput, setContextInput] = useState('');
  const [showContextInput, setShowContextInput] = useState(false);

  const handleProcessQuestions = async () => {
    if (questions.length === 0) {
      alert('No questions available to process');
      return;
    }

    if (!knowledgeBaseReady) {
      alert('Knowledge base is not ready. Please upload training documents first.');
      return;
    }

    setIsProcessing(true);
    setStatus('processing');

    try {
      // Use the API service which handles FormData correctly
      const contextInputs = contextInput.trim() 
        ? [contextInput.trim()]
        : [];

      const result = await apiService.processQuestionsWithContext(questions, contextInputs);

      if (result.status === 'success') {
        setStatus('success');
        setProcessingResult(result as ProcessingResult);
      } else {
        setStatus('error');
        setProcessingResult(result as ProcessingResult);
      }
    } catch (error) {
      console.error('Question processing failed:', error);
      setStatus('error');
      setProcessingResult({ 
        status: 'error',
        message: 'Failed to process questions',
        answers: {}, 
        answers_generated: 0, 
        needs_context: [],
        remaining_clarifications: 0
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDownloadResults = () => {
    if (!processingResult || !processingResult.answers) return;

    // Convert answers object to array format for CSV
    const answersArray = Object.entries(processingResult.answers).map(([question, answer]) => ({
      question,
      answer
    }));

    const csvContent = [
      ['Question', 'Answer'].join(','),
      ...answersArray.map(item => [
        `"${item.question.replace(/"/g, '""')}"`,
        `"${item.answer.replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `rfp_answers_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const getStatusIcon = () => {
    switch (status) {
      case 'processing':
        return <Loader className="animate-spin text-blue-500" size={20} />;
      case 'success':
        return <CheckCircle className="text-green-500" size={20} />;
      case 'error':
        return <AlertCircle className="text-red-500" size={20} />;
      default:
        return <Brain className="text-gray-400" size={20} />;
    }
  };

  const getStatusMessage = () => {
    switch (status) {
      case 'processing':
        return 'Processing questions with AI...';
      case 'success':
        return `Successfully processed ${processingResult?.answers_generated || 0} questions`;
      case 'error':
        return 'Failed to process questions';
      default:
        return 'Ready to process questions with AI';
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-lg p-6">
      <div className="mb-6">
        <h3 className="text-xl font-semibold text-gray-900 mb-2">
          Step 3: AI Processing & Answer Generation
        </h3>
        <p className="text-gray-600">
          Process extracted questions using your knowledge base to generate intelligent answers.
        </p>
      </div>

      {/* Prerequisites Check */}
      {(!knowledgeBaseReady || questions.length === 0) && (
        <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
          <div className="flex items-center gap-2">
            <AlertCircle className="text-yellow-600" size={20} />
            <p className="text-yellow-800 font-medium">Prerequisites Required</p>
          </div>
          <div className="text-yellow-700 text-sm mt-1 space-y-1">
            {!knowledgeBaseReady && <p>• Knowledge base must be built (Step 1)</p>}
            {questions.length === 0 && <p>• RFP questions must be extracted (Step 2)</p>}
          </div>
        </div>
      )}

      {/* Questions Summary */}
      {questions.length > 0 && (
        <div className="mb-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
          <div className="flex items-center gap-2 mb-2">
            <FileText className="text-blue-600" size={20} />
            <h4 className="font-medium text-blue-800">Questions Ready for Processing</h4>
          </div>
          <p className="text-blue-700 text-sm">
            {questions.length} questions extracted and ready for AI processing
          </p>
        </div>
      )}

      {/* Context Input Section */}
      <div className="mb-6">
        <div className="flex items-center justify-between mb-3">
          <h4 className="text-md font-medium text-gray-900">Additional Context (Optional)</h4>
          <button
            onClick={() => setShowContextInput(!showContextInput)}
            className="text-blue-600 hover:text-blue-700 flex items-center gap-1 text-sm"
          >
            <PlusCircle size={16} />
            {showContextInput ? 'Hide' : 'Add Context'}
          </button>
        </div>

        {showContextInput && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="space-y-3"
          >
            <textarea
              value={contextInput}
              onChange={(e) => setContextInput(e.target.value)}
              placeholder="Enter any additional context that might help generate better answers (e.g., company information, specific requirements, project details...)"
              className="w-full p-3 border border-gray-300 rounded-lg resize-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              rows={4}
            />
            <p className="text-xs text-gray-500">
              This context will be included with each question to help generate more relevant and personalized answers.
            </p>
          </motion.div>
        )}
      </div>

      {/* Processing Section */}
      <div className="border-2 border-dashed border-gray-300 rounded-lg p-6">
        <div className="text-center space-y-4">
          <div className="flex justify-center">
            {getStatusIcon()}
          </div>
          
          <div>
            <h4 className="text-lg font-medium text-gray-900">
              AI Question Processing
            </h4>
            <p className="text-sm text-gray-500 mt-1">
              {getStatusMessage()}
            </p>
          </div>

          <motion.button
            onClick={handleProcessQuestions}
            disabled={!knowledgeBaseReady || questions.length === 0 || isProcessing}
            className="w-full px-4 py-3 bg-gradient-to-r from-purple-600 to-blue-600 text-white rounded-lg hover:from-purple-700 hover:to-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-all duration-300 font-medium"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            {isProcessing ? (
              <div className="flex items-center justify-center gap-2">
                <Loader className="animate-spin" size={16} />
                Processing with AI...
              </div>
            ) : (
              <div className="flex items-center justify-center gap-2">
                <Brain size={16} />
                Process {questions.length} Questions
                {contextInput.trim() && <span className="text-xs">(with context)</span>}
              </div>
            )}
          </motion.button>
        </div>
      </div>

      {/* Processing Results */}
      {processingResult && status === 'success' && (
        <motion.div 
          className="mt-6 space-y-4"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
        >
          {/* Success Summary */}
          <div className="p-4 bg-green-50 border border-green-200 rounded-lg">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <CheckCircle className="text-green-500" size={20} />
                <h4 className="font-medium text-green-800">Processing Complete!</h4>
              </div>
              <motion.button
                onClick={handleDownloadResults}
                className="px-3 py-1 bg-green-600 text-white rounded-lg hover:bg-green-700 text-sm flex items-center gap-1"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                <Download size={14} />
                Download CSV
              </motion.button>
            </div>
            <div className="text-sm text-green-700 mt-2 space-y-1">
              <p>📊 Questions processed: {processingResult.answers_generated}</p>
              <p>🎯 Success rate: {((processingResult.answers_generated / questions.length) * 100).toFixed(1)}%</p>
              {contextInput.trim() && <p>📝 Processed with additional context</p>}
              {processingResult.remaining_clarifications > 0 && (
                <p>⚠️ {processingResult.remaining_clarifications} questions need more context</p>
              )}
            </div>
          </div>

          {/* Answers Preview */}
          <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
            <h5 className="font-medium text-gray-900 mb-3">Generated Answers Preview</h5>
            <div className="space-y-3 max-h-60 overflow-y-auto">
              {Object.entries(processingResult.answers).slice(0, 3).map(([question, answer], index) => (
                <div key={index} className="bg-white p-3 rounded border">
                  <div className="text-sm font-medium text-gray-800 mb-1">
                    Q: {question.substring(0, 100)}...
                  </div>
                  <div className="text-sm text-gray-600">
                    A: {answer.substring(0, 150)}...
                  </div>
                </div>
              ))}
              {Object.keys(processingResult.answers).length > 3 && (
                <p className="text-sm text-gray-500 text-center">
                  ... and {Object.keys(processingResult.answers).length - 3} more answers
                </p>
              )}
            </div>
          </div>
        </motion.div>
      )}

      {processingResult && status === 'error' && (
        <motion.div 
          className="mt-6 p-4 bg-red-50 border border-red-200 rounded-lg"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <div className="flex items-center gap-2 mb-2">
            <AlertCircle className="text-red-500" size={20} />
            <h4 className="font-medium text-red-800">Processing Failed</h4>
          </div>
          <p className="text-sm text-red-700">{processingResult.status}</p>
        </motion.div>
      )}
    </div>
  );
};

export default RAGProcessorNew;
